SELECT
 (SELECT count(*)=3 AND bool_and(c.relrowsecurity) FROM pg_class c WHERE c.oid IN(to_regclass('petro_private.service_refund_requests'),to_regclass('petro_private.service_refund_withdrawals'),to_regclass('petro_private.service_refund_commands')))
 AND NOT EXISTS(SELECT 1 FROM pg_class c CROSS JOIN(VALUES('anon'),('authenticated'),('service_role'))r(name) WHERE c.oid IN(to_regclass('petro_private.service_refund_requests'),to_regclass('petro_private.service_refund_withdrawals'),to_regclass('petro_private.service_refund_commands')) AND has_table_privilege(r.name,c.oid,'SELECT,INSERT,UPDATE,DELETE'))
 AND(SELECT count(*)=3 AND bool_and(p.prosecdef AND p.proconfig=ARRAY['search_path=""']::text[] AND has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('service_role',p.oid,'EXECUTE')) FROM pg_proc p WHERE p.oid IN(to_regprocedure('public.petro_service_order_refund_requests(uuid)'),to_regprocedure('public.petro_request_service_refund(uuid,text,text,text,text)'),to_regprocedure('public.petro_withdraw_service_refund(uuid,bigint,text)')))
 AND(SELECT count(*)=2 AND bool_and(NOT p.prosecdef AND p.proconfig=ARRAY['search_path=""']::text[] AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('service_role',p.oid,'EXECUTE')) FROM pg_proc p WHERE p.oid IN(to_regprocedure('petro_private.service_refund_order_access(uuid,boolean)'),to_regprocedure('petro_private.guard_refund_request_history()')))
 AND(SELECT count(*)=3 FROM pg_trigger WHERE NOT tgisinternal AND tgenabled='O' AND tgname IN('service_refund_request_immutable','service_refund_withdrawal_immutable','service_refund_command_immutable')) AS present;
